        owner=new Pilot(world,1);enemy=new Pilot(world,2);NetworkTeamHelper.setPlayerTeam(owner,"blue");NetworkTeamHelper.setPlayerTeam(enemy,"red");owner.setPosition(10000.5,4,10000.5);enemy.setPosition(10000.5,4,10000.5);
        BlockPos pos=new BlockPos(10000,4,10000);world.setBlockState(pos,WarTechContent.PLANNING_TERMINAL.getDefaultState(),3);WarTechContent.PLANNING_TERMINAL.onBlockPlacedBy(world,pos,world.getBlockState(pos),owner,new ItemStack(WarTechContent.PLANNING_TERMINAL));terminal=(TileEntityPlanningTerminal)world.getTileEntity(pos);owner.openContainer=new ContainerPlanningTerminal(owner,terminal,null);owner.openContainer.windowId=87;
        check("owner_terminal",terminal.mayUse(owner),"actual tile scope");check("foreign_terminal",!terminal.mayUse(enemy),"red denied blue");
        grad=new EntityModernVehicle(world,ModernVehicleProfile.GRAD);spawn(grad,10020,10000);for(int i=0;i<2;i++)grad.setInventorySlotContents(i,new ItemStack(ModernVehicleProfile.GRAD.ammunition()));
        tel=new EntityStrategicTel(world,StrategicSystemProfile.ISKANDER);spawn(tel,10050,10000);tel.setInventorySlotContents(0,new ItemStack(WarTechContent.ITEM_ISKANDER_MISSILE));
