        plane=new EntityWarTechAircraft(world,WarTechEntityProfile.MQ_9_REAPER);spawn(plane,10100,10000);plane.setInventorySlotContents(0,new ItemStack(WarTechContent.MQ9_PAYLOAD,1,0));plane.setInventorySlotContents(1,new ItemStack(WarTechContent.MQ9_PAYLOAD,1,0));
