        PlanningAssetRegistry.refresh(world);plan=new AttackOperation();plan.scope=PlanningAccessPolicy.scope(owner);plan.author=owner.getUniqueID();plan.title="Native combined planning QA";
        guidedPlan=new AttackOperation();guidedPlan.scope=plan.scope;guidedPlan.author=owner.getUniqueID();guidedPlan.title="Wizard exact tubes";NBTTagCompound guidedAsset=PlanningAssetRegistry.describe(guidedGrad).write();java.util.List<NBTTagCompound> choices=AttackPlanBuilder.weapons(guidedAsset,guidedPlan);check("wizard_actual_loaded_tubes",choices.size()==1 && choices.get(0).getInteger("Available")==2,choices);guidedGrad.setDeployed(true);check("wizard_deployed_stores_remain_selectable",AttackPlanBuilder.weapons(PlanningAssetRegistry.describe(guidedGrad).write(),guidedPlan).size()==1,"loading lock is separate from launchable stores");guidedGrad.setDeployed(false);guidedPlan.steps.addAll(AttackPlanBuilder.build(guidedPlan,guidedAsset,choices.get(0).getString("WeaponKey"),2,10035,3,10400,20,30,false));check("wizard_native_preflight",OperationScheduler.validate(world,guidedPlan).isEmpty(),guidedPlan.write());
