        if(tick==260){PlanningWorldData d=PlanningWorldData.get(world);PlanningWorldData restored=new PlanningWorldData();restored.readFromNBT(d.writeToNBT(new NBTTagCompound()));check("persistent_schedule",restored.operations.containsKey(plan.id) && restored.operations.get(plan.id).started==plan.started,"saved tick clock and step identities");}
        if(tick%200==0 && plan!=null)System.out.println("PLANNINGQA tick="+tick+" state="+plan.state+" steps="+plan.steps.stream().map(s->s.action+":"+s.phase+":"+s.reason+":"+s.emitted).collect(java.util.stream.Collectors.toList()));
        if(tick==4000 || plan!=null && tick>600 && (plan.state==AttackOperation.State.COMPLETE || plan.state==AttackOperation.State.PARTIAL))finish();
