    private void finish()throws Exception{
        check("wizard_native_two_physical_releases",guidedPlan.steps.stream().allMatch(s->s.phase==AttackOperation.Phase.DONE) && guidedPlan.steps.stream().mapToInt(s->s.emitted).sum()==2 && guidedGrad.loadedCount()==0,guidedPlan.write());
        for(AttackOperation.Step s:plan.steps)check("native_"+s.action+"_"+s.asset,s.phase==AttackOperation.Phase.DONE,s.phase+" "+s.reason+" emitted="+s.emitted+" accepted="+s.accepted+" actual="+s.actual);
        AttackOperation.Step salvo=plan.steps.get(1);check("actual_salvo_admission",salvo.emitted==2 && salvo.flights.size()==2 && salvo.actual>=salvo.accepted,"real successful spawns");check("consumption_grad",grad.loadedCount()==0,grad.loadedCount());check("consumption_tel",tel.getStackInSlot(0).isEmpty(),tel.getMissileMask());check("consumption_platform",fp7.getStackInSlot(0).isEmpty(),fp7.getStackInSlot(0));check("carrier_two_releases",plane.getStackInSlot(0).isEmpty() && plane.getStackInSlot(1).isEmpty(),plane.getStackInSlot(0)+" "+plane.getStackInSlot(1));
        check("both_cruise_carriers_released",cruiseTargets.size()==2 && cruisePlane.getStackInSlot(0).isEmpty() && cruiseUav.getStackInSlot(0).isEmpty(),cruiseTargets);
        boolean sourceCounted=false;for(AttackOperation.Step s:plan.steps)sourceCounted|=s.flights.contains(cruiseUav.getUniqueID()) || s.flights.contains(cruisePlane.getUniqueID()) || s.flights.contains(plane.getUniqueID());check("carriers_never_counted_as_released_weapons",!sourceCounted,"only spawned weapons and released one-way UAV");
        TeamIntelData intel=PlanningWorldData.get(world).intel.get(plan.scope);check("native_recon_contact",intel!=null && intel.contacts.containsKey(PlanningAssetRegistry.key(hostile)),intel==null?"none":intel.contacts.keySet());if(intel!=null){NBTTagCompound n=intel.viewport(10000,10000,512);check("bounded_recon_snapshot",n.getTagList("Cells",10).tagCount()<=256 && n.getIntArray("Terrain").length==1296,n.getTagList("Cells",10).tagCount());}
        NetworkTeamHelper.setPlayerTeam(owner,"red");check("team_switch_revokes_open_session",PlanningService.handle(owner,87,new NBTTagCompound())==null,"old scope access revoked");
        for(Entity entity:new ArrayList<>(world.loadedEntityList))if(entity instanceof EntityWarTechBase && entity.posX>9000 && entity.posX<16000)entity.setDead();for(ForgeChunkManager.Ticket t:tickets)ForgeChunkManager.releaseTicket(t);
        JsonObject out=new JsonObject();out.addProperty("complete",true);out.add("cases",cases);out.add("failures",new Gson().toJsonTree(failures));out.addProperty("resources",MissileChunkLoader.diagnostics(world));Files.write(Paths.get("flightqa-report.json"),new GsonBuilder().setPrettyPrinting().create().toJson(out).getBytes(StandardCharsets.UTF_8));MinecraftForge.EVENT_BUS.unregister(this);FMLCommonHandler.instance().getMinecraftServerInstance().initiateShutdown();
    }
